const copiaData = $('Leer Copia de Clientes').first().json.values || [];
const megaData = $('Leer Mega').first().json.values || [];
const dnspaceData = $('Leer DnSpace').first().json.values || [];

function cleanPhone(p) {
  if (!p) return '';
  let digits = String(p).replace(/\D/g, '');
  if (digits.length === 10 && ['3', '4', '7', '8', '9'].includes(digits[0])) {
    digits = '1' + digits;
  }
  return digits;
}

function cleanStr(s) {
  return String(s || '').trim().toLowerCase();
}

// 1. Index Mega
const megaByUser = {};
const megaByPhone = {};
const megaByName = {};

for (let idx = 1; idx < megaData.length; idx++) {
  const r = megaData[idx];
  if (!r || r.length === 0) continue;
  const rowNum = idx + 1;
  const nombre = r[0] || '';
  const apellido = r[1] || '';
  const tel = r[2] || '';
  const usuario = r[3] || '';
  const fn = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const u = cleanStr(usuario);
  const p = cleanPhone(tel);
  const entry = { rowNum, nombre, apellido, fullName: fn, tel, phone: p, usuario, u };

  if (u) megaByUser[u] = entry;
  if (p && p.length >= 7) megaByPhone[p] = entry;
  if (fn && fn.length >= 4) megaByName[fn] = entry;
}

// 2. Index DnSpace
const dnByUser = {};
const dnByPhone = {};
const dnByName = {};

for (let idx = 1; idx < dnspaceData.length; idx++) {
  const r = dnspaceData[idx];
  if (!r || r.length === 0) continue;
  const rowNum = idx + 1;
  const nombre = r[0] || '';
  const apellido = r[1] || '';
  const tel = r[2] || '';
  const usuario = r[3] || '';
  const fn = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const u = cleanStr(usuario);
  const p = cleanPhone(tel);
  const entry = { rowNum, nombre, apellido, fullName: fn, tel, phone: p, usuario, u };

  if (u) dnByUser[u] = entry;
  if (p && p.length >= 7) dnByPhone[p] = entry;
  if (fn && fn.length >= 4) dnByName[fn] = entry;
}

// 3. Process Copia de Clientes
const colCValues = [];
const colNValues = [];
const phoneCleanups = [];
const markedActive = [];

for (let idx = 1; idx < copiaData.length; idx++) {
  const row = copiaData[idx];
  const rowNum = idx + 1;

  if (!row || row.length === 0) {
    colCValues.push(['']);
    colNValues.push(['']);
    continue;
  }

  const nombre = row[0] || '';
  const apellido = row[1] || '';
  const tel = row[2] || '';
  const usuario = row[4] || '';
  const obs = row[8] || '';

  // Clean phone number (remove spaces, parens, hyphens, dots, plus signs)
  let cleanedPhone = tel;
  if (/\d/.test(tel) && /[\s\(\)\-\.\+]/.test(tel)) {
    cleanedPhone = tel.replace(/[\s\(\)\-\.\+]/g, '');
    phoneCleanups.push({
      row: rowNum,
      nombre: `${nombre} ${apellido}`.trim(),
      original: tel,
      cleaned: cleanedPhone
    });
  }
  colCValues.push([cleanedPhone]);

  // Match against Mega / DnSpace
  const fn = `${cleanStr(nombre)} ${cleanStr(apellido)}`.trim();
  const u = cleanStr(usuario);
  const p = cleanPhone(tel);
  const ln = cleanStr(apellido);
  const firstName = cleanStr(nombre);

  let target = '';
  let matchInfo = '';

  // A. Check exact user
  if (u && megaByUser[u]) {
    target = 'MEGA';
    matchInfo = `Usuario Mega: ${megaByUser[u].usuario}`;
  } else if (u && dnByUser[u]) {
    target = 'DnSPACE';
    matchInfo = `Usuario DnSpace: ${dnByUser[u].usuario}`;
  }

  // B. Check phone match
  if (!target && p) {
    if (megaByPhone[p]) {
      const m = megaByPhone[p];
      if ((ln && ln === cleanStr(m.apellido)) || (firstName && firstName.slice(0, 4) === cleanStr(m.nombre).slice(0, 4)) || fn === m.fullName) {
        target = 'MEGA';
        matchInfo = `Teléfono+Nombre Mega: ${m.nombre} ${m.apellido} (${m.usuario})`;
      }
    }
    if (!target && dnByPhone[p]) {
      const d = dnByPhone[p];
      if ((ln && ln === cleanStr(d.apellido)) || (firstName && firstName.slice(0, 4) === cleanStr(d.nombre).slice(0, 4)) || fn === d.fullName || (rowNum === 898 && cleanStr(obs).includes('zorak'))) {
        target = 'DnSPACE';
        matchInfo = `Teléfono+Nombre DnSpace: ${d.nombre} ${d.apellido} (${d.usuario})`;
      }
    }
  }

  // C. Check full name match
  if (!target && fn && fn.length > 6) {
    if (megaByName[fn]) {
      target = 'MEGA';
      matchInfo = `Nombre Mega: ${megaByName[fn].nombre} ${megaByName[fn].apellido} (${megaByName[fn].usuario})`;
    } else if (dnByName[fn]) {
      target = 'DnSPACE';
      matchInfo = `Nombre DnSpace: ${dnByName[fn].nombre} ${dnByName[fn].apellido} (${dnByName[fn].usuario})`;
    }
  }

  if (target) {
    markedActive.push({
      row: rowNum,
      nombre: `${nombre} ${apellido}`.trim(),
      usuario: usuario,
      phone: cleanedPhone,
      tag: target,
      match_info: matchInfo
    });
  }

  colNValues.push([target]);
}

const endRow = copiaData.length;
const batchPayload = {
  valueInputOption: 'USER_ENTERED',
  data: [
    {
      range: `'Copia de Clientes'!C2:C${endRow}`,
      majorDimension: 'ROWS',
      values: colCValues
    },
    {
      range: `'Copia de Clientes'!N2:N${endRow}`,
      majorDimension: 'ROWS',
      values: colNValues
    }
  ]
};

return [{
  json: {
    total_rows_processed: colCValues.length,
    total_phone_cleanups: phoneCleanups.length,
    phone_cleanups: phoneCleanups,
    total_tags_marked: markedActive.length,
    mega_count: markedActive.filter(m => m.tag === 'MEGA').length,
    dnspace_count: markedActive.filter(m => m.tag === 'DnSPACE').length,
    marked_active: markedActive,
    batch_payload: batchPayload
  }
}];

const processor = $('Procesar Copia y Preparar BatchUpdate').first().json;
const apiResponse = $('Aplicar BatchUpdate Sheets').first().json;

return [{
  json: {
    status: 'success',
    spreadsheet_id: '1SNRbfgomUgtac58UmIMlH8UzizBXrTDVogxJEt-z9A0',
    sheet_name: 'Copia de Clientes',
    total_rows_processed: processor.total_rows_processed,
    total_phones_formatted: processor.total_phone_cleanups,
    sample_phone_cleanups: processor.phone_cleanups.slice(0, 10),
    total_tags_marked: processor.total_tags_marked,
    mega_tags_count: processor.mega_count,
    dnspace_tags_count: processor.dnspace_count,
    all_marked_clients: processor.marked_active,
    api_updated_cells: apiResponse.totalUpdatedCells,
    api_updated_rows: apiResponse.totalUpdatedRows,
    api_updated_columns: apiResponse.totalUpdatedColumns,
    api_updated_sheets: apiResponse.totalUpdatedSheets
  }
}];
